  const sels = [
    ['[data-question-text="template_edit_request"] .question-text-input', '[data-question-text-submit="template_edit_request"]'],
    ['[data-question-other="template_edit_confirm"] .question-other-input', '[data-question-other="template_edit_confirm"] .question-other-submit'],
  ];
  const deadline = Date.now() + 20000;
  while (Date.now() < deadline) {
    for (const pair of sels) {
      const el = document.querySelector(pair[0]);
      if (!el || el.disabled) continue;
      if (el.offsetParent === null) continue;
      if (el.value) { el.value = ''; el.dispatchEvent(new Event('input', { bubbles: true })); }
      return pair[0];
    }
    await new Promise((r) => setTimeout(r, 250));
  }
  return '';
})()

