(() => {
  const regions = Array.from(document.querySelectorAll('#preview-root [data-region-id]'));
  const box = regions.find((r) => {
    const n = r.querySelector('.region-name');
    const l = r.querySelector('.wtm-metric-label');
    return (n && (n.innerText || '').includes("设备耗电排名")) ||
           (l && (l.innerText || '').includes("设备耗电排名"));
  });
  if (!box) return false;
  const holder = box.querySelector('.wch-canvas');
  if (!holder || !window.echarts || !window.echarts.getInstanceByDom) return false;
  const inst = window.echarts.getInstanceByDom(holder);
  if (!inst) return false;
  const opt = inst.getOption() || {};
  const series = opt.series || [];
  for (const s of series) {
    const ml = s && s.markLine;
    if (!ml) continue;
    for (const d of (ml.data || [])) {
      if (d && (d.name === '关注阈值' || Number(d.yAxis) === 500)) return true;
    }
  }
  return false;
})()

